import{D as e,f as t,u as n}from"./runtime-core.esm-bundler-BHJ3o1LK.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E5%B7%A5%E7%A8%8B/%E7%BD%91%E9%A1%B5%E9%9D%A2%E6%9D%BF%E9%87%8D%E5%90%AF%E8%87%AA%E5%B7%B1%EF%BC%88%E9%80%9A%E7%94%A8%E5%AE%9E%E7%8E%B0%E6%89%8B%E5%86%8C%EF%BC%89.html","title":"网页面板重启自己（通用实现手册）","lang":"zh-CN","frontmatter":{"title":"网页面板重启自己（通用实现手册）","icon":"mdi:autorenew","sort":5,"description":"网页面板重启自己（通用实现手册） 状态：母本 · 现行（2026-11-06，从 pass-up.ops 与 infra/wsl-manager 两次实战提炼） 这份文档的用法：新项目要做「界面上一个按钮 → 一键重建 + 重启服务 → 页面自己回来」时， 把这一篇整份丢给 AI，让它按 §4–§8 施工、按 §10 落文件、按 §12 验收、按 §1...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"网页面板重启自己（通用实现手册）\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-11-06T05:47:01.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"桥黎\\",\\"url\\":\\"\\"}]}"],["meta",{"property":"og:url","content":"https://docs.cqlql.top/%E5%B7%A5%E7%A8%8B/%E7%BD%91%E9%A1%B5%E9%9D%A2%E6%9D%BF%E9%87%8D%E5%90%AF%E8%87%AA%E5%B7%B1%EF%BC%88%E9%80%9A%E7%94%A8%E5%AE%9E%E7%8E%B0%E6%89%8B%E5%86%8C%EF%BC%89.html"}],["meta",{"property":"og:site_name","content":"开发笔记"}],["meta",{"property":"og:title","content":"网页面板重启自己（通用实现手册）"}],["meta",{"property":"og:description","content":"网页面板重启自己（通用实现手册） 状态：母本 · 现行（2026-11-06，从 pass-up.ops 与 infra/wsl-manager 两次实战提炼） 这份文档的用法：新项目要做「界面上一个按钮 → 一键重建 + 重启服务 → 页面自己回来」时， 把这一篇整份丢给 AI，让它按 §4–§8 施工、按 §10 落文件、按 §12 验收、按 §1..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-11-06T05:47:01.000Z"}],["meta",{"property":"article:modified_time","content":"2026-11-06T05:47:01.000Z"}]]},"git":{"createdTime":1793944021000,"updatedTime":1793944021000,"contributors":[{"name":"cql","username":"cql","email":"cql.ql@qq.com","commits":1,"url":"https://github.com/cql"}]},"readingTime":{"minutes":27.46,"words":8239},"filePathRelative":"工程/网页面板重启自己（通用实现手册）.md","autoDesc":true}`),a={name:`网页面板重启自己（通用实现手册）.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="网页面板重启自己-通用实现手册" tabindex="-1"><a class="header-anchor" href="#网页面板重启自己-通用实现手册"><span>网页面板重启自己（通用实现手册）</span></a></h1><blockquote><p>状态：<strong>母本 · 现行</strong>（2026-11-06，从 <code>pass-up.ops</code> 与 <code>infra/wsl-manager</code> 两次实战提炼）</p><p><strong>这份文档的用法</strong>：新项目要做「界面上一个按钮 → 一键重建 + 重启服务 → 页面自己回来」时， 把这一篇<strong>整份</strong>丢给 AI，让它按 §4–§8 施工、按 §10 落文件、按 §12 验收、按 §11 换常量。 不需要再去读那两个项目的源码。施工中报错先查 §9（坑）与 §13（症状速查）。</p><p>⚠️ <strong>本文修订</strong>《桌面启动器与本地网页面板（通用实现手册）》§8 / §15 里 「不做自重建」的结论。那条结论的前提是「重建失败发生在隐藏进程里、无人看见」—— 本文用 §2 的三条硬约定解决它。<strong>不满足 §1.3 的前提时，仍应照母本「不做」</strong>， 并把「为什么不做」写进项目文档，别让后来的人以为点了重启会生效。</p><p>本文只写<strong>通用判据与可复制规格</strong>；项目常量（exe 名、端口、配置目录、构建命令）见 §11。</p></blockquote><hr><h2 id="_0-一页速用" tabindex="-1"><a class="header-anchor" href="#_0-一页速用"><span>0. 一页速用</span></a></h2><p>目标形态，五段交接，<strong>顺序不能换</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>页面「重启」按钮 → POST /api/restart（confirm + rebuild）</span></span>
<span class="line"><span>  → [1] 服务端可选重建，产物落到 &lt;tool&gt;.next.exe（失败就地停，服务照旧在跑）</span></span>
<span class="line"><span>  → [2] 先回 200（显式 Content-Length）→ 拉起 __restart 接手进程（detached，输出进日志）</span></span>
<span class="line"><span>  → [3] 旧进程 shutdown（让出端口）→ exit 0（原守护随之结束）</span></span>
<span class="line"><span>  → [4] 接手：等端口空 → 把 next.exe 换到正式 exe → __takeover 同端口同 token 起服务</span></span>
<span class="line"><span>  → [5] 前端轮询 /api/health，boot_id 变了才 location.reload()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三句红线，先记住：</p><ol><li>🔴 <strong>重建失败就地停</strong>。构建可能产出一个起不来的二进制，而交接之后没有回头路。</li><li>🔴 <strong>不换 token</strong>。前端 token 通常只在内存 + 地址栏；换掉之后轮询 health 会一直 401， <code>boot_id</code> 永远拿不到，界面会把一次<strong>成功</strong>的重启误报成失败。</li><li>🔴 <strong>判据只有 <code>boot_id</code></strong>。交接失败时旧进程会刻意原地活着，那时「服务还在」与 「重启成功」在界面上完全一样；传输层失败也不是失败。</li></ol><hr><h2 id="_1-适用与不适用" tabindex="-1"><a class="header-anchor" href="#_1-适用与不适用"><span>1. 适用与不适用</span></a></h2><h3 id="_1-1-适用" tabindex="-1"><a class="header-anchor" href="#_1-1-适用"><span>1.1 适用</span></a></h3><ul><li>本机<strong>单二进制</strong>工具（Go / Rust / Node 打包均可），已有或想要一个 <code>127.0.0.1</code> 的 Web 面板。</li><li>开发时反复改代码，需要「重建 → 重启」这条循环不再靠手工四步。</li><li>平台是 Windows（本文的交接机制是 Windows 专属，见 §3）。</li></ul><h3 id="_1-2-不适用-别硬套" tabindex="-1"><a class="header-anchor" href="#_1-2-不适用-别硬套"><span>1.2 不适用（别硬套）</span></a></h3><table><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">为什么</th><th style="text-align:left;">该怎么做</th></tr></thead><tbody><tr><td style="text-align:left;">服务端 / 多实例 / 有负载均衡</td><td style="text-align:left;">没有「单个本机进程」可换</td><td style="text-align:left;">走正常的滚动发布</td></tr><tr><td style="text-align:left;">前端产物由别的进程托管（独立 dev server）</td><td style="text-align:left;">二进制里没有需要重建的嵌入产物</td><td style="text-align:left;">只重启后端，构建交给前端工具链</td></tr><tr><td style="text-align:left;">无法写本机日志文件</td><td style="text-align:left;">detached 进程没有控制台，启动失败原因会静默丢掉</td><td style="text-align:left;">先补日志落点，见 §1.3</td></tr><tr><td style="text-align:left;">Linux / macOS</td><td style="text-align:left;">那边有 <code>syscall.Exec</code>，同 PID 换映像更干净</td><td style="text-align:left;">用 exec，不要照抄本文的接手进程</td></tr></tbody></table><h3 id="_1-3-🔴-开工前必须满足的四个前提" tabindex="-1"><a class="header-anchor" href="#_1-3-🔴-开工前必须满足的四个前提"><span>1.3 🔴 开工前必须满足的四个前提</span></a></h3><p><strong>缺任何一个，就别做</strong>，照母本 §8 保留「不做自重建」并在文档里写明理由。</p><table><thead><tr><th style="text-align:left;">前提</th><th style="text-align:left;">缺了会怎样</th></tr></thead><tbody><tr><td style="text-align:left;">构建输出能同时<strong>回 HTTP 响应</strong>并<strong>落日志</strong></td><td style="text-align:left;">重建失败在隐藏进程里无人看见 —— 这正是母本当初否决它的正当理由</td></tr><tr><td style="text-align:left;">有一个本机日志文件作为 detached 进程的输出落点</td><td style="text-align:left;">新进程启动失败时只剩「连不上」，原因查不到</td></tr><tr><td style="text-align:left;">单实例凭据可复用（端口 + token 落盘，如 <code>ui.json</code> 0600）</td><td style="text-align:left;">页面回来后 401，或新进程绑到别的端口</td></tr><tr><td style="text-align:left;">前端能读到「进程实例标识」（<code>boot_id</code>）</td><td style="text-align:left;">只能按「服务还在」判，交接失败会被报成成功</td></tr></tbody></table><hr><h2 id="_2-三条硬约定-当初「不做」的理由怎么被解决" tabindex="-1"><a class="header-anchor" href="#_2-三条硬约定-当初「不做」的理由怎么被解决"><span>2. 三条硬约定：当初「不做」的理由怎么被解决</span></a></h2><table><thead><tr><th style="text-align:left;">母本 §8 的顾虑</th><th style="text-align:left;">本文的对策</th><th style="text-align:left;">不做会怎样</th></tr></thead><tbody><tr><td style="text-align:left;">重建链路长、失败面大</td><td style="text-align:left;"><strong>先重建、成功才交接</strong>；失败回 500 + 构建输出进响应</td><td style="text-align:left;">构建出一个起不来的二进制，服务彻底没了</td></tr><tr><td style="text-align:left;">失败发生在隐藏进程、无人看见</td><td style="text-align:left;">新进程 stdout/stderr <strong>重定向到日志</strong>；确认弹窗显示日志路径</td><td style="text-align:left;">启动失败原因静默丢掉，人只能对着「连不上」猜</td></tr><tr><td style="text-align:left;">链路长，人会懒得点、干脆不重启</td><td style="text-align:left;"><strong>过期检测自动勾「先重建」</strong>；前端产物新鲜时跳过耗时的前端构建</td><td style="text-align:left;">忘了勾 = 用旧二进制起来，症状是「我明明改了，界面怎么没变」</td></tr></tbody></table><blockquote><p>这三条互为前提：只做第一条（失败就地停）而不做第二条（日志落点）， 等于把「失败得看得见」换成了「失败得见得着、但成功失败都查不到」。</p></blockquote><hr><h2 id="_3-机制选型-windows-上没有-exec" tabindex="-1"><a class="header-anchor" href="#_3-机制选型-windows-上没有-exec"><span>3. 机制选型：Windows 上没有 exec</span></a></h2><table><thead><tr><th style="text-align:left;">机制</th><th style="text-align:left;">平台</th><th style="text-align:left;">评价</th></tr></thead><tbody><tr><td style="text-align:left;"><code>syscall.Exec</code>（同 PID 换映像）</td><td style="text-align:left;">Linux / macOS</td><td style="text-align:left;">同终端、同 cwd/env，失败原因就在原终端里；<strong>但 Windows 没有</strong></td></tr><tr><td style="text-align:left;">退出码 75 + <code>exe.new</code> 换身 + 启动器循环重拉</td><td style="text-align:left;">Windows</td><td style="text-align:left;">复用守护；代价是要改启动器（CRLF / ASCII 注释 / 隐藏窗口 <code>pause</code> 规则），多一处状态机</td></tr><tr><td style="text-align:left;"><strong>detached 接手进程 + 内部子命令</strong>（本文选它）</td><td style="text-align:left;">Windows</td><td style="text-align:left;">启动器<strong>一行不改</strong>；失败面收敛到「旧进程 / 接手进程」两处，日志同一份</td></tr></tbody></table><p><strong>为什么不用守护循环</strong>：启动器是这类工具里最脆的一层（批处理解析、代码页、隐藏窗口）， 让它承担「退出码 → 换文件 → 重拉」的状态机会把风险放到最不该放的地方。 独立接手进程只认三个参数，行为可单测。</p><p><strong>Windows 上必须显式补 exec 免费给的两件事</strong>：</p><table><thead><tr><th style="text-align:left;">缺什么</th><th style="text-align:left;">判据 / 做法</th><th style="text-align:left;">漏了的症状</th></tr></thead><tbody><tr><td style="text-align:left;">监听地址要先被让出来</td><td style="text-align:left;"><code>WaitPortFree(addr, 60s)</code>：反复尝试 <code>net.Listen(addr)</code>，<strong>能绑上</strong>就是「可以接手」；不查 PID（会复用、会因权限查不到）</td><td style="text-align:left;">新进程绑不上端口，界面「重启完连不上了」</td></tr><tr><td style="text-align:left;">新进程不能共享原控制台</td><td style="text-align:left;"><code>DETACHED_PROCESS</code> + <code>CREATE_NEW_PROCESS_GROUP</code>；stdout/stderr 接日志文件</td><td style="text-align:left;">关掉原窗口会把新服务一起带走；或输出静默丢掉</td></tr></tbody></table><hr><h2 id="_4-代码分层与依赖方向" tabindex="-1"><a class="header-anchor" href="#_4-代码分层与依赖方向"><span>4. 代码分层与依赖方向</span></a></h2><p>以 Go 为例（其它语言照搬职责划分）。<strong>依赖只许单向</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>main → ui → restart → shared</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><table><thead><tr><th style="text-align:left;">模块</th><th style="text-align:left;">职责</th><th style="text-align:left;">不能做</th></tr></thead><tbody><tr><td style="text-align:left;"><code>internal/restart/</code></td><td style="text-align:left;">纯机制：<code>WaitPortFree</code> / <code>ReplaceBinary</code> / <code>Spawn</code> / <code>Rebuild</code> / <code>Check</code>（过期判定）</td><td style="text-align:left;"><strong>不反向 import <code>ui</code></strong>；不含 HTTP、不含业务状态</td></tr><tr><td style="text-align:left;"><code>internal/ui/restart.go</code></td><td style="text-align:left;">三个接口、确认令牌、六道门、交接编排</td><td style="text-align:left;">不自己实现重建命令</td></tr><tr><td style="text-align:left;">根包 <code>restartchild.go</code></td><td style="text-align:left;">接手子进程的入口（它要调 <code>ui.CmdUI</code>）</td><td style="text-align:left;">放根包是为了<strong>不成环</strong>：<code>restart</code> 不能反向依赖 <code>ui</code></td></tr><tr><td style="text-align:left;"><code>web/src/features/system/</code></td><td style="text-align:left;">确认弹窗 + <code>restartFlow</code> 判定纯函数</td><td style="text-align:left;">判定逻辑不依赖 DOM / React，必须能脱离浏览器单测</td></tr><tr><td style="text-align:left;"><code>internal/ui/ui.go</code></td><td style="text-align:left;">内部标记 <code>__takeover</code>：同端口、复用 token、单例重试、不新开浏览器</td><td style="text-align:left;">不生成新 token</td></tr></tbody></table><p><strong>平台差异用 build tag 拆</strong>：<code>spawn_windows.go</code> 实现 detached；<code>spawn_other.go</code> <strong>明确报错</strong> （「该能力只在 Windows 可用」），而不是用一套没验证过的 POSIX detach 假装能用。</p><p><strong>内部标记不进注册表</strong>：<code>__restart</code> / <code>__takeover</code> 用下划线开头，不出现在 <code>--help</code>、 README、菜单的能力探测里；参数传错只能退出（它必须以服务身份起来，否则没人绑端口）。</p><hr><h2 id="_5-接口契约" tabindex="-1"><a class="header-anchor" href="#_5-接口契约"><span>5. 接口契约</span></a></h2><p>三个接口，全部走现有 token 校验；写操作 <code>POST</code> 且校验 <code>Origin</code>。 字段名可按项目信封调整（本文用 <code>{ok, data, error}</code>），<strong>语义不能改</strong>。</p><h3 id="_5-1-get-api-health" tabindex="-1"><a class="header-anchor" href="#_5-1-get-api-health"><span>5.1 <code>GET /api/health</code></span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>{ ok: true, data: { ok: true, boot_id: &quot;&lt;这个进程实例&gt;&quot; } }</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>boot_id</code> 是<strong>进程级随机值</strong>（8 字节随机数，取不到退化成时间戳，<strong>绝不返回空串</strong>）。 不用 PID 代替：PID 会变，但「服务还在」与「重启成功」必须能分开。</p><h3 id="_5-2-get-api-restart-确认视图" tabindex="-1"><a class="header-anchor" href="#_5-2-get-api-restart-确认视图"><span>5.2 <code>GET /api/restart</code>（确认视图）</span></a></h3><table><thead><tr><th style="text-align:left;">字段</th><th style="text-align:left;">类型</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><code>confirm_token</code></td><td style="text-align:left;">string</td><td style="text-align:left;">绑「进程实例 + 端口 + token」；页面是上一个进程打开的就得 409</td></tr><tr><td style="text-align:left;"><code>impact</code></td><td style="text-align:left;">string[]</td><td style="text-align:left;">影响面原文，弹窗里逐条摊开。<strong>不用 Markdown 加粗</strong>：JSX 纯文本渲染会原样显示星号</td></tr><tr><td style="text-align:left;"><code>build_command</code></td><td style="text-align:left;">string[]</td><td style="text-align:left;">「会跑：…」给人看，不是给人执行</td></tr><tr><td style="text-align:left;"><code>binary_stale</code> / <code>stale_reason</code></td><td style="text-align:left;">bool / string</td><td style="text-align:left;">前端据此<strong>自动勾</strong>「先重建」</td></tr><tr><td style="text-align:left;"><code>log_path</code></td><td style="text-align:left;">string</td><td style="text-align:left;">启动失败原因只在这里</td></tr><tr><td style="text-align:left;"><code>port</code> / <code>exe</code> / <code>exe_exists</code></td><td style="text-align:left;"></td><td style="text-align:left;">当前事实；exe 不在时没什么可重启</td></tr><tr><td style="text-align:left;"><code>task_running</code></td><td style="text-align:left;">bool</td><td style="text-align:left;">有长任务在跑时弹窗提前提示（真正的拦截在 POST）</td></tr><tr><td style="text-align:left;"><code>note</code></td><td style="text-align:left;">string</td><td style="text-align:left;">非空 = 现在不能重启（凭据读不到 / exe 不在），前端<strong>不给按钮</strong></td></tr></tbody></table><h3 id="_5-3-post-api-restart" tabindex="-1"><a class="header-anchor" href="#_5-3-post-api-restart"><span>5.3 <code>POST /api/restart</code></span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>请求：{ &quot;rebuild&quot;: true|false, &quot;confirm&quot;: &quot;sha256:…&quot; }   // 只认这两个字段，多余的直接拒</span></span>
<span class="line"><span>200： { ok:true, data:{ restarting:true, rebuild, build_output, boot_id } }  // 显式 Content-Length</span></span>
<span class="line"><span>409： confirm 过期 / 长任务在跑 / 接手凭据读不到</span></span>
<span class="line"><span>500： 重建失败（服务照旧在跑）/ 拼响应失败（不交接）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>请求体要读干净再往下走</strong>：socket 上还有未读数据时关闭会发 RST，可能让浏览器把 <strong>已经完整收到的响应</strong>也丢掉；而这次不会正常返回 handler。</p><h3 id="_5-4-六道门-服务端-enforce-前端只是交互" tabindex="-1"><a class="header-anchor" href="#_5-4-六道门-服务端-enforce-前端只是交互"><span>5.4 六道门（服务端 enforce，前端只是交互）</span></a></h3><table><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">门</th><th style="text-align:left;">理由</th></tr></thead><tbody><tr><td style="text-align:left;">①</td><td style="text-align:left;"><code>confirm_token</code> 绑「进程实例 + 端口 + token」，不一致 409</td><td style="text-align:left;">页面是上一个实例打开时，刚才看到的那份对照已不成立</td></tr><tr><td style="text-align:left;">②</td><td style="text-align:left;">会写外部状态的长任务在跑时 <strong>409 拒绝</strong></td><td style="text-align:left;">远端/数据库正在写，拦腰截断会留半状态（只提示「会中断」不够）</td></tr><tr><td style="text-align:left;">③</td><td style="text-align:left;">重建按固定顺序执行，<strong>失败就地停、服务照旧在跑</strong></td><td style="text-align:left;">交接之后没有回头路</td></tr><tr><td style="text-align:left;">④</td><td style="text-align:left;">接手进程复用 <code>ui.json</code> 的 port + token；令牌<strong>不进命令行</strong></td><td style="text-align:left;">换 token → 前端 401 → 成功被误报成失败；命令行参数在任务管理器里看得见</td></tr><tr><td style="text-align:left;">⑤</td><td style="text-align:left;">响应必须显式 <code>Content-Length</code>；先回 200 再 Shutdown + 退出；<strong>拉起失败就不退出</strong></td><td style="text-align:left;">退出而新进程没起来 = 服务彻底没了，界面只会显示「连不上」</td></tr><tr><td style="text-align:left;">⑥</td><td style="text-align:left;">判据只有 <code>boot_id</code> 变了；传输层失败不是失败；同路径换二进制必须拒绝</td><td style="text-align:left;">见 §0 红线 3 与 §9 坑 5</td></tr></tbody></table><blockquote><p><strong>不要求输 <code>yes</code></strong>：重启是<strong>本机动作</strong>（不碰远端），二次确认弹窗已把影响面逐条摊开。 给主路径多加一次输入，只会让人更少用它。远端的写操作才需要 <code>yes</code> + 服务端预检。</p></blockquote><hr><h2 id="_6-交接链路-顺序与判据" tabindex="-1"><a class="header-anchor" href="#_6-交接链路-顺序与判据"><span>6. 交接链路（顺序与判据）</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>[HTTP handler]</span></span>
<span class="line"><span>  1. 校验 confirm / 任务门 / 凭据可读性</span></span>
<span class="line"><span>  2. 可选 Rebuild（context.Background()，禁用 r.Context()：请求会断，构建要 30~40 秒）</span></span>
<span class="line"><span>  3. 留痕（交接之后这个进程就没了，日志必须写在前面）</span></span>
<span class="line"><span>  4. 自己 json.Marshal + 显式 Content-Length + WriteHeader(200) + Write + Flush</span></span>
<span class="line"><span>  5. sleep ~500ms（让浏览器开始轮询 health）</span></span>
<span class="line"><span>  6. Spawn(接手进程)  ← 失败：只记日志、return，**不退出**、不写第二个响应体</span></span>
<span class="line"><span>  7. srv.Shutdown(ctx, 3s)（关监听，把端口让给接手进程）</span></span>
<span class="line"><span>  8. exit(0)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[接手进程 __restart &lt;addr&gt; &lt;targetExe&gt; &lt;newExe|-&gt;]</span></span>
<span class="line"><span>  1. WaitPortFree(addr, 60s)</span></span>
<span class="line"><span>  2. newExe != &quot;-&quot; → ReplaceBinary(newExe, targetExe)</span></span>
<span class="line"><span>     ⚠️ 换不上**不是致命**：如实记日志，继续用现有二进制起服务</span></span>
<span class="line"><span>  3. 以 __takeover --port &lt;addr 的端口&gt; 启动服务（从 ui.json 读 token）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>接手进程的三个参数含义</strong>（混填是最隐蔽的一类 bug）：</p><table><thead><tr><th style="text-align:left;">参数</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>&lt;addr&gt;</code></td><td style="text-align:left;">等它空出来 = 旧进程已让位的<strong>唯一</strong>信号</td></tr><tr><td style="text-align:left;"><code>&lt;targetExe&gt;</code></td><td style="text-align:left;"><code>ReplaceBinary</code> 的<strong>目标</strong>（正式 exe），不是「从哪个文件起来」</td></tr><tr><td style="text-align:left;"><code>&lt;newExe｜-&gt;</code></td><td style="text-align:left;">重建产物；<code>-</code> 表示没重建（此时<strong>不跑</strong> <code>ReplaceBinary</code>）</td></tr></tbody></table><p>「从哪个文件起来」是第四个隐含值：重建过就从 <code>next.exe</code> 起，否则从正式 exe 起。 把两者混填会让 <code>ReplaceBinary</code> 变成 <code>next.exe → next.exe</code> 的空操作， <strong>表面成功、正式 exe 永远停在旧版本</strong>，而日志照样写着「新二进制已就位」。</p><p><strong>为什么响应必须显式 <code>Content-Length</code></strong>：Go 在 handler 返回之前 <code>Flush</code> 会退化成 chunked， 而结束块（<code>0\\r\\n\\r\\n</code>）要等 handler 返回才写 —— 可下一步就退出进程了，那个结束块 永远发不出去。客户端收到的是<strong>截断报文</strong>（<code>Failed to fetch</code>）， 于是「重启明明成功了，界面上却报失败」。</p><p><strong>为什么先拉起再 Shutdown</strong>：反过来接手进程要干等，而这段时间端口还占着。 <code>__takeover</code> 里还要<strong>带重试拿单实例锁</strong>（见 §9 坑 2）。</p><hr><h2 id="_7-重建-顺序、超时、产物命名、过期判定" tabindex="-1"><a class="header-anchor" href="#_7-重建-顺序、超时、产物命名、过期判定"><span>7. 重建：顺序、超时、产物命名、过期判定</span></a></h2><h3 id="_7-1-顺序-前端-→-后端-因为产物被-embed-进二进制" tabindex="-1"><a class="header-anchor" href="#_7-1-顺序-前端-→-后端-因为产物被-embed-进二进制"><span>7.1 顺序（前端 → 后端，因为产物被 embed 进二进制）</span></a></h3><table><thead><tr><th style="text-align:left;">步</th><th style="text-align:left;">命令</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;"><code>npm install</code>（仅依赖缺失时）</td><td style="text-align:left;">冷启动兜底</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;"><code>npm test</code></td><td style="text-align:left;">测试目录常故意不在 <code>tsconfig.include</code> 里，类型错误只能靠跑一遍发现</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;"><code>npm run typecheck</code></td><td style="text-align:left;">同上</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;"><code>npm run build</code></td><td style="text-align:left;">生成前端产物</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;"><code>go build -o &lt;tool&gt;.next.exe .</code></td><td style="text-align:left;">把新产物 embed 进去</td></tr></tbody></table><ul><li><strong>每步都有超时上界</strong>（300s）：一次卡住的构建会把「正在重建」状态锁死，界面上连按钮都点不动。</li><li><strong>npm 只在前端真的过期或依赖缺失时跑</strong>：写死每次都跑会白等 30~40 秒，代价会让人干脆不点重启。</li><li><strong>产物落在 <code>&lt;tool&gt;.next.exe</code></strong>：正在运行的 exe 被 Windows 锁着，直接 <code>build -o &lt;tool&gt;.exe</code> 只会拿到一句毫无信息量的 sharing violation。旧进程退出后由接手进程改名换上去。</li><li><strong>回读确认产物存在</strong>：「命令没报错」≠「真的产出了新二进制」。</li><li><strong>源码不在 exe 同目录时明确失败</strong>：在一个只有 exe 的目录里「构建成功」是最坏的假话。</li></ul><h3 id="_7-2-命令拼装-踩过两次的坑" tabindex="-1"><a class="header-anchor" href="#_7-2-命令拼装-踩过两次的坑"><span>7.2 命令拼装（踩过两次的坑）</span></a></h3><table><thead><tr><th style="text-align:left;">规则</th><th style="text-align:left;">原因</th></tr></thead><tbody><tr><td style="text-align:left;"><code>name</code> 与 <code>args</code> <strong>分开传</strong>，绝不自己拼命令行字符串</td><td style="text-align:left;">Go 的 exec 在 Windows 按 <code>CommandLineToArgvW</code> 组装/转义，而 <code>cmd.exe</code> 不按那套解析；含空格的 <code>go.exe</code> 路径（默认就在 <code>C:\\Program Files\\Go\\</code>）必然坏掉，症状是 <code>&#39;C:\\Program&#39; 不是内部或外部命令</code>，看起来像「go 没装」</td></tr><tr><td style="text-align:left;"><strong>后端构建命令直接 exec</strong>，不经 <code>cmd.exe</code></td><td style="text-align:left;">同上，加多少引号都救不回来</td></tr><tr><td style="text-align:left;">只有 <code>npm</code>（<code>.cmd</code>）需要 <code>cmd.exe /d /c</code></td><td style="text-align:left;">Windows 上直接 exec 一个 <code>.cmd</code> 在各版本 Go 上行为不稳；<code>/d</code> 是不要执行 AutoRun</td></tr><tr><td style="text-align:left;">构建窗口隐藏（<code>CREATE_NO_WINDOW</code>）</td><td style="text-align:left;">构建那几十秒里不该一直有个黑框</td></tr><tr><td style="text-align:left;">输出合并、只回传末尾 60 行</td><td style="text-align:left;">失败原因总在最后；几百行进 HTTP 响应没意义</td></tr></tbody></table><h3 id="_7-3-过期检测-check-只有一份实现" tabindex="-1"><a class="header-anchor" href="#_7-3-过期检测-check-只有一份实现"><span>7.3 过期检测（<code>Check</code>）只有一份实现</span></a></h3><p><strong>两条判据</strong>：前端源码比前端产物新（或产物不存在）→ 需要前端重建； <strong>后端源码或前端产物</strong>比 exe 新 → 需要后端重编。</p><p>🔴 <strong>前端产物本身也算后端输入</strong>：它被 embed 进二进制。漏掉它就会出现 「前端重建了但没重编 Go，界面看着变了、其实跑的是旧后端」。 🔴 <strong>所有 embed 输入目录都要算</strong>（例：备份脚本、模板、静态资源目录）， 漏一个就是「脚本改了、部署出去还是旧的」。</p><p><strong>运行态文件一律排除</strong>（<code>*.exe</code> / <code>*.exe~</code> / <code>*.log</code> / <code>*.env</code> / <code>servers.json</code> / <code>ui.json</code> / <code>node_modules</code> / <code>.git</code> / IDE 目录）：否则「先重建」会<strong>永远勾着</strong> —— 一个永远为真的告警等于没有告警。</p><p><strong>基线文件拿不到 = 过期，不是「不知道」</strong>：没有产物可谈，谈不上新鲜；理由里写明 是哪个文件不存在，界面才说得清要重建什么。</p><hr><h2 id="_8-前端-判定纯函数与确认弹窗" tabindex="-1"><a class="header-anchor" href="#_8-前端-判定纯函数与确认弹窗"><span>8. 前端：判定纯函数与确认弹窗</span></a></h2><h3 id="_8-1-判定必须与渲染分离" tabindex="-1"><a class="header-anchor" href="#_8-1-判定必须与渲染分离"><span>8.1 判定必须与渲染分离</span></a></h3><p>把下面三个函数放进<strong>不依赖 DOM / React</strong> 的模块（例：<code>restartFlow.ts</code>）， 这样 <code>node --test</code> 之类能直接跑，不用起浏览器。它们守的是「两种失败长得很像」：</p><table><thead><tr><th style="text-align:left;">交接成功</th><th style="text-align:left;">交接失败</th></tr></thead><tbody><tr><td style="text-align:left;">响应可能丢掉，<code>boot_id</code> <strong>会变</strong></td><td style="text-align:left;">响应同样可能丢掉，<code>boot_id</code> <strong>永远不变</strong></td></tr></tbody></table><table><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">规则</th></tr></thead><tbody><tr><td style="text-align:left;"><code>defaultRebuild(info)</code></td><td style="text-align:left;"><code>info.binary_stale === true</code>。写死 <code>true</code> 白等几十秒；写死 <code>false</code> 会用旧二进制起来</td></tr><tr><td style="text-align:left;"><code>judgeHandover(before, after)</code></td><td style="text-align:left;"><code>after === before</code> → <code>unchanged</code>；<code>after</code> 非空且不同 → <code>restarted</code>；<code>before</code> 为空、<code>after</code> 为空/<code>null</code> → <code>unknown</code></td></tr><tr><td style="text-align:left;"><code>timeoutMessage(info, seconds)</code></td><td style="text-align:left;">必须<strong>带上日志路径</strong>：失败原因只在那里</td></tr><tr><td style="text-align:left;"><code>shouldRefreshView(status)</code></td><td style="text-align:left;">409 / 500 后重新拉一次视图，否则下次点「执行」还拿旧 <code>confirm_token</code></td></tr></tbody></table><p>🔴 <strong><code>unknown</code> 不许显示成成功或失败</strong>：拿不到重启前的 <code>boot_id</code> 只能说「没法确认」； 重启期间连接断几秒是「还没到」，不是结论。</p><h3 id="_8-2-请求与轮询" tabindex="-1"><a class="header-anchor" href="#_8-2-请求与轮询"><span>8.2 请求与轮询</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>1. before = (await health()).boot_id        // 读不到 → &#39;&#39;，如实退化成「没法确认」</span></span>
<span class="line"><span>2. POST /api/restart</span></span>
<span class="line"><span>   - 只有 ApiError（服务端明确回 JSON 错误）才说明它没动手 → 提示 + 刷新视图</span></span>
<span class="line"><span>   - 传输层异常（Failed to fetch / 连接被重置）→ 忽略，转去等 boot_id</span></span>
<span class="line"><span>3. 每 1s 轮询 health，直到 boot_id 变了 → location.reload()</span></span>
<span class="line"><span>4. 上界 120s；超时报「看起来没重启成功」+ 日志路径，构建输出打到 console</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-3-弹窗与按钮" tabindex="-1"><a class="header-anchor" href="#_8-3-弹窗与按钮"><span>8.3 弹窗与按钮</span></a></h3><table><thead><tr><th style="text-align:left;">元素</th><th style="text-align:left;">要求</th></tr></thead><tbody><tr><td style="text-align:left;">标题</td><td style="text-align:left;">「重启 &lt;工具名&gt;？」/「重建并重启 &lt;工具名&gt;？」</td></tr><tr><td style="text-align:left;">顶部一句</td><td style="text-align:left;">说清「重启后沿用<strong>当前端口与访问令牌</strong>，页面自动回来」</td></tr><tr><td style="text-align:left;">影响面</td><td style="text-align:left;"><code>impact</code> 逐条 <code>&lt;li&gt;</code> 摊开：会中断什么、重建失败会怎样、Windows 没有 exec、日志在哪、按 <code>boot_id</code> 判断</td></tr><tr><td style="text-align:left;">「先重建」复选框</td><td style="text-align:left;">默认值来自 <code>defaultRebuild</code>；<strong>只在第一次拿到事实时设一次</strong>，之后别覆盖用户的手动选择</td></tr><tr><td style="text-align:left;">过期提示</td><td style="text-align:left;"><code>binary_stale</code> 时警告「不重建的话跑的还是旧代码」，并给出 <code>stale_reason</code></td></tr><tr><td style="text-align:left;">会跑什么</td><td style="text-align:left;"><code>build_command</code> 逐条列出</td></tr><tr><td style="text-align:left;">日志路径</td><td style="text-align:left;"><code>log_path</code> 明写出来</td></tr><tr><td style="text-align:left;">执行按钮</td><td style="text-align:left;">危险色（danger），文案「执行」；<strong>点完就关弹窗</strong>，让全局 loading 与消息承担等待，别让弹窗挂 120 秒</td></tr></tbody></table><p><strong>按钮放全局工具栏</strong>（不是某一页的头部）：它是对<strong>服务本身</strong>的动作，与当前看哪一页无关； 改完前端就该在当前页直接重启。工具栏不随页面卸载，轮询不会被切页打断。</p><p>⚠️ <strong>弹窗必须走 App 上下文</strong>（<code>App.useApp()</code> 的 <code>modal</code> / <code>message</code>），不要用静态方法： antd v6 + React 19 下静态方法渲染到独立 React root、拿不到主题，真机表现为 「点了按钮，什么都没发生」。</p><hr><h2 id="_9-十二个坑-都是实测踩过的" tabindex="-1"><a class="header-anchor" href="#_9-十二个坑-都是实测踩过的"><span>9. 十二个坑（都是实测踩过的）</span></a></h2><table><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">症状</th><th style="text-align:left;">根因</th><th style="text-align:left;">修法</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">重启后页面一直转圈，最后报「没重启成功」，但服务是新的</td><td style="text-align:left;">新进程换了 token，前端轮询 health 一直 401</td><td style="text-align:left;"><code>__takeover</code> 从 <code>ui.json</code> 复用 port + token；<code>GET /api/restart</code> 先校验凭据可读且与当前一致</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">重启后「服务还在」，其实是旧进程；日志里接手进程只开了个浏览器</td><td style="text-align:left;">命名互斥体要等旧进程 <code>exit</code> 才由内核释放，而 <code>WaitPortFree</code> 只看端口（关监听在 exit 之前），两者差几毫秒</td><td style="text-align:left;">接手进程<strong>带重试拿锁</strong>（8s 上界）；拿不到就如实失败，不要走「已有实例 → 只开浏览器」那条路</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">重启成功了，界面却报 <code>Failed to fetch</code></td><td style="text-align:left;">handler 返回前 Flush 退化成 chunked，结束块随进程退出永远发不出去</td><td style="text-align:left;">自己序列化 + 显式 <code>Content-Length</code></td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;"><code>&#39;C:\\Program&#39; 不是内部或外部命令</code>，看起来像 go 没装</td><td style="text-align:left;">把含空格的 go 路径拼进 <code>cmd.exe /c</code> 字符串；加引号也没用（转义规则不同）</td><td style="text-align:left;"><code>name</code> 与 <code>args</code> 分开传；后端构建直接 exec，只有 <code>npm.cmd</code> 走 <code>cmd.exe /d /c</code></td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">日志写着「新二进制已就位」，正式 exe 却永远是旧的</td><td style="text-align:left;"><code>ReplaceBinary(new, target)</code> 里 <code>new == target</code>，<code>os.Rename</code> 做了空操作却报成功</td><td style="text-align:left;"><strong>同路径必须拒绝</strong>；「从哪个文件起来」与「换到哪个文件」分开两个值传</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">第一次「带重建」成功后，第二次不重建的重启报「文件被删了」</td><td style="text-align:left;">Windows 上 <code>os.Executable()</code> 返回<strong>进程映像加载时</strong>的路径：从 <code>next.exe</code> 起来、改名成正式 exe 后仍返回 <code>next.exe</code></td><td style="text-align:left;"><code>TargetExe()</code> 走按后缀的 <code>NormalizeExePath</code>（<code>.next.exe</code> → <code>.exe</code>）；<strong>按文件名判，不靠探测文件在不在</strong></td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">改了脚本 / 前端，重启后跑的还是旧的</td><td style="text-align:left;">过期检测只算了 <code>*.go</code>，漏掉 embed 输入目录与前端产物</td><td style="text-align:left;">白名单含所有 embed 输入 + <code>前端产物/index.html</code></td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">「先重建」永远勾着</td><td style="text-align:left;">运行态文件（<code>*.exe~</code> / <code>*.log</code> / <code>ui.json</code> / <code>node_modules</code>）被算成源码</td><td style="text-align:left;">白名单 + prune，运行态文件一律排除</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">交接后服务彻底没了，日志里什么都没有</td><td style="text-align:left;">detached 进程没有控制台可写，启动失败原因静默丢掉</td><td style="text-align:left;"><code>Spawn</code> 把 stdout/stderr 接日志文件；界面显示路径</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">重启成功两秒后服务又没了</td><td style="text-align:left;">新进程共享父进程控制台，关窗口的 <code>CTRL_CLOSE_EVENT</code> 把它一起带走</td><td style="text-align:left;"><code>DETACHED_PROCESS</code> + <code>CREATE_NEW_PROCESS_GROUP</code></td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">影响面文案里出现字面量 <code>**加粗**</code></td><td style="text-align:left;">文案直接塞进 JSX 当纯文本渲染</td><td style="text-align:left;">要强调就换措辞，不写 Markdown</td></tr><tr><td style="text-align:left;">12</td><td style="text-align:left;">明明回了 200，浏览器却说响应丢了</td><td style="text-align:left;">请求体没读干净就关连接，socket 上残留数据触发 RST</td><td style="text-align:left;"><code>io.Copy(io.Discard, r.Body)</code> 再往下走</td></tr></tbody></table><hr><h2 id="_10-文件清单" tabindex="-1"><a class="header-anchor" href="#_10-文件清单"><span>10. 文件清单</span></a></h2><p><strong>新增</strong>（路径按 §11 换成新项目的名字）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>internal/restart/restart.go            # 常量、WaitPortFree、ReplaceBinary、NormalizeExePath、TargetExe</span></span>
<span class="line"><span>internal/restart/spawn_windows.go      # Spawn（detached + 日志句柄）、Hide（构建不弹窗口）</span></span>
<span class="line"><span>internal/restart/spawn_other.go        # 非 Windows 明确报错，不假装能用</span></span>
<span class="line"><span>internal/restart/rebuild.go            # Rebuild：构建顺序、超时、产物回读</span></span>
<span class="line"><span>internal/restart/staleness.go          # Check：过期判定（唯一一份实现）+ BuildCommands</span></span>
<span class="line"><span>internal/restart/*_test.go             # 交接 / 重建顺序 / 过期判定</span></span>
<span class="line"><span>internal/ui/restart.go                 # health / restart 三个接口、确认令牌、六道门、交接编排</span></span>
<span class="line"><span>internal/ui/restart_test.go            # 409、重建失败不交接、Content-Length、Spawn 失败不退出</span></span>
<span class="line"><span>&lt;根包&gt;/restartchild.go                 # __restart 接手子进程入口（调 CmdUI）</span></span>
<span class="line"><span>&lt;根包&gt;/restartchild_test.go            # 参数解析、内部命令不进注册表</span></span>
<span class="line"><span>web/src/features/system/types.ts       # view / result 类型</span></span>
<span class="line"><span>web/src/features/system/api.ts         # 三个接口，只发请求不写判定</span></span>
<span class="line"><span>web/src/features/system/restartFlow.ts # 判定纯函数（可脱离浏览器单测）</span></span>
<span class="line"><span>web/src/features/system/components/RestartPanel.tsx  # 弹窗 + 轮询</span></span>
<span class="line"><span>web/test/restartFlow.test.ts           # 判定用例</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>修改</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>main.go                        # 注册内部 __restart（不进 usage / 菜单）；抽出共用的 ui 入口</span></span>
<span class="line"><span>internal/ui/ui.go              # 三个路由；CmdUI 的 __takeover 分支（复用 token + 单例重试 + 不新开浏览器）</span></span>
<span class="line"><span>internal/ui/background.go      # acquireSingletonRetry（接手专用，8s 上界）</span></span>
<span class="line"><span>web/src/App.tsx                # 全局顶部工具栏；访问过的页面仍保持挂载</span></span>
<span class="line"><span>web/src/index.css              # 工具栏样式；侧栏高度 / sticky 不变</span></span>
<span class="line"><span>AGENTS.md / docs/ui.md / docs/one-click-launch.md  # 结论、红线、验收（见 §14）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>不该动</strong>：启动器（<code>.cmd</code> / <code>.lnk</code>）、配置模板、远端相关代码。 整条链路是「本机换个进程」，与它们无关。</p><hr><h2 id="_11-换项目只改这些" tabindex="-1"><a class="header-anchor" href="#_11-换项目只改这些"><span>11. 换项目只改这些</span></a></h2><table><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">常量 / 位置</th><th style="text-align:left;">本手册示例</th><th style="text-align:left;">换项目时要确认</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">正式 exe / 重建产物</td><td style="text-align:left;"><code>ops.exe</code> / <code>ops.next.exe</code></td><td style="text-align:left;">名字与后缀；<code>.gitignore</code> 要忽略 <code>*.exe</code></td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">内部子命令名</td><td style="text-align:left;"><code>__restart</code> / <code>__takeover</code></td><td style="text-align:left;">保持下划线开头，别进注册表</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">配置目录与凭据文件</td><td style="text-align:left;"><code>%APPDATA%\\pass-up\\ui.json</code>（0600，port + token）</td><td style="text-align:left;">覆盖变量；<code>GET /api/restart</code> 要能校验它</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">日志文件</td><td style="text-align:left;"><code>ops-ui.log</code>（追加 + 轮转上限）</td><td style="text-align:left;">detached 进程与后台守护<strong>共用一份</strong>打开逻辑</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">默认端口 / 递增上限</td><td style="text-align:left;">7788 / 20</td><td style="text-align:left;">与同机其它工具错开</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">单实例名</td><td style="text-align:left;"><code>Local\\&lt;vendor&gt;-&lt;tool&gt;-ui-&lt;hash&gt;</code></td><td style="text-align:left;">名字带配置目录指纹；接手要重试拿锁</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">构建命令</td><td style="text-align:left;"><code>npm test / typecheck / build</code> → <code>go build -o …next.exe .</code></td><td style="text-align:left;">换成该项目的真实构建链；<code>test/</code> 是否在 tsc include 里</td></tr><tr><td style="text-align:left;">8</td><td style="text-align:left;">embed 输入</td><td style="text-align:left;"><code>deploy/backup/**</code>、<code>web/dist/index.html</code></td><td style="text-align:left;"><strong>逐个列全</strong>，漏一个就是隐性过期</td></tr><tr><td style="text-align:left;">9</td><td style="text-align:left;">长任务判据</td><td style="text-align:left;"><code>backupBusy()</code></td><td style="text-align:left;">换成「会写外部状态的任务」的判定函数</td></tr><tr><td style="text-align:left;">10</td><td style="text-align:left;">HTTP 信封 / token 头</td><td style="text-align:left;"><code>{ok,data,error}</code> / <code>X-Ops-Token</code></td><td style="text-align:left;">前端 <code>request()</code> 与后端 <code>writeAPI</code> 对齐</td></tr><tr><td style="text-align:left;">11</td><td style="text-align:left;">影响面文案</td><td style="text-align:left;">5 条</td><td style="text-align:left;">按项目改「会中断什么」「日志在哪」，别照抄</td></tr><tr><td style="text-align:left;">12</td><td style="text-align:left;">等新进程上界</td><td style="text-align:left;">120s</td><td style="text-align:left;">冷启动慢的机器要放宽</td></tr></tbody></table><p><strong>落地顺序</strong>：<code>restart</code> 机制 + 过期判定 → 三个接口 + 六道门 → <code>__restart</code> 子进程 + <code>__takeover</code> 复用凭据 → 前端判定纯函数 + 弹窗 + 工具栏 → 文档与红线 → 测试矩阵 → 真机真跑。</p><blockquote><p>🔴 每一步都要能回答「失败了会怎样」。这整条链路最怕的不是报错， 是<strong>「看起来正常」</strong>：日志写着成功、页面也能连上，但跑的是旧二进制或旧进程。</p></blockquote><hr><h2 id="_12-测试与验收" tabindex="-1"><a class="header-anchor" href="#_12-测试与验收"><span>12. 测试与验收</span></a></h2><h3 id="_12-1-自动-ci-能跑-不真起进程、不碰真配置" tabindex="-1"><a class="header-anchor" href="#_12-1-自动-ci-能跑-不真起进程、不碰真配置"><span>12.1 自动（CI 能跑，不真起进程、不碰真配置）</span></a></h3><table><thead><tr><th style="text-align:left;">测试点</th><th style="text-align:left;">断言什么</th></tr></thead><tbody><tr><td style="text-align:left;"><code>WaitPortFree</code></td><td style="text-align:left;">端口空了立即返回；被占时超时并说清「仍占着」</td></tr><tr><td style="text-align:left;"><code>ReplaceBinary</code></td><td style="text-align:left;">覆盖目标成功；<strong>同路径拒绝</strong>；产物不存在时给出可记进日志的原因（非致命）</td></tr><tr><td style="text-align:left;"><code>NormalizeExePath</code> / <code>TargetExe</code></td><td style="text-align:left;"><code>.next.exe</code> → <code>.exe</code>；正式 exe 原样返回；空路径返回空</td></tr><tr><td style="text-align:left;"><code>Check</code>（过期）</td><td style="text-align:left;">前端源码过期、后端源码过期、embed 输入过期、前端产物比 exe 新；运行态文件<strong>不触发</strong>；产物缺失判为过期</td></tr><tr><td style="text-align:left;"><code>Rebuild</code></td><td style="text-align:left;">顺序对（前端四步 → 后端构建）；前端新鲜时跳过 npm；<strong>任一步失败立即停、不继续 go build</strong>；源码根缺失时明确拒绝</td></tr><tr><td style="text-align:left;">确认令牌</td><td style="text-align:left;">同实例稳定；换实例 / 换端口后失效</td></tr><tr><td style="text-align:left;">六道门</td><td style="text-align:left;">错 confirm 409、任务在跑 409、凭据读不到 409、重建失败 500 且<strong>不交接/不退出</strong></td></tr><tr><td style="text-align:left;">交接参数</td><td style="text-align:left;">重建过从 <code>next.exe</code> 起；不重建从正式 exe 起且 <code>newExe == &quot;-&quot;</code>；正式 exe 与「换到哪」是两个值</td></tr><tr><td style="text-align:left;">响应</td><td style="text-align:left;">显式 <code>Content-Length</code>；<code>boot_id</code> 是重启前的那个</td></tr><tr><td style="text-align:left;">Spawn 失败</td><td style="text-align:left;">200 已写出、进程<strong>不退出</strong>、不写第二个响应体</td></tr><tr><td style="text-align:left;">单例重试</td><td style="text-align:left;">前几次拿不到锁最终成功 → 不判失败；一直拿不到 → 如实失败</td></tr><tr><td style="text-align:left;">前端判定</td><td style="text-align:left;"><code>defaultRebuild</code> / <code>judgeHandover</code> 真值表 / 超时文案带日志路径 / 409-500 后刷新视图</td></tr></tbody></table><h3 id="_12-2-覆盖变量下的真跑-用临时配置目录-独立端口-不写真配置、不碰真远端" tabindex="-1"><a class="header-anchor" href="#_12-2-覆盖变量下的真跑-用临时配置目录-独立端口-不写真配置、不碰真远端"><span>12.2 覆盖变量下的真跑（<strong>用临时配置目录 + 独立端口</strong>，不写真配置、不碰真远端）</span></a></h3><ol><li>起界面：配置目录覆盖变量指到临时目录，显式 <code>--port</code> 绑一个空闲端口，<code>--no-open</code>。</li><li><code>GET /api/health</code> 记下 <code>before.boot_id</code>；<code>GET /api/restart</code> 核对 <code>note</code> 为空、影响面 5 条、日志路径。</li><li><strong>触发过期</strong>：<code>touch</code> 一个前端源文件 → 再取一次视图，应得 <code>binary_stale=true</code> 且 <code>build_command</code> 列出完整前端构建链（这一步同时验证「自动勾先重建」）。</li><li><code>POST /api/restart</code> 带 <code>rebuild=true</code> → 应拿得到完整 200（含 <code>build_output</code>）， <strong>不要因为传输层异常就判失败</strong>。</li><li>轮询 health 直到 <code>boot_id</code> 变化；核对正式 exe 的 mtime 变了、<code>next.exe</code> 已不在、 日志里有「等端口让出来 → 新二进制已就位 → 沿用原令牌」。</li><li>再点一次 <code>rebuild=false</code>：只换进程、日志里<strong>没有</strong> <code>ReplaceBinary</code>，<code>boot_id</code> 再次变化。</li><li>用错 <code>confirm</code> 发一次 → 409，之后 health 仍 200（服务没被动过）。</li><li>收尾用项目自己的「关闭界面」停掉验证进程，别留后台进程。</li></ol><h3 id="_12-3-真机人工-windows-逐条打勾" tabindex="-1"><a class="header-anchor" href="#_12-3-真机人工-windows-逐条打勾"><span>12.3 真机人工（Windows，逐条打勾）</span></a></h3><ul><li>[ ] 浏览器里点「重启」→ 弹窗逐条列出影响面、复选框、构建命令、日志路径。</li><li>[ ] 勾「先重建」→ 页面断连几秒后<strong>自己回来</strong>，不用重新复制地址、不用重新双击启动器。</li><li>[ ] 不勾「先重建」→ 同样能回来，且 exe 的 mtime 不变。</li><li>[ ] 故意让构建失败（例如临时改坏一个 <code>.ts</code>）→ 提示「重建失败、服务照旧在跑」，页面仍在。</li><li>[ ] 备份/部署类长任务在跑时点「重启」→ 被拒绝并说明原因。</li><li>[ ] 前端产物里确认工具栏样式与弹窗文案；无头浏览器截图核对布局与按钮<strong>不是 disabled</strong>。</li><li>[ ] 原标签页的 token 若因重启流程之外的操作换过，重新双击启动器能打开带新 token 的地址。</li></ul><hr><h2 id="_13-故障速查-按症状查" tabindex="-1"><a class="header-anchor" href="#_13-故障速查-按症状查"><span>13. 故障速查（按症状查）</span></a></h2><table><thead><tr><th style="text-align:left;">症状</th><th style="text-align:left;">最可能的原因</th><th style="text-align:left;">先看哪节</th></tr></thead><tbody><tr><td style="text-align:left;">页面一直转圈，最后报「没重启成功」，但服务是新的</td><td style="text-align:left;">换了 token / <code>boot_id</code> 判据写错</td><td style="text-align:left;">§9-1、§8.1</td></tr><tr><td style="text-align:left;">「服务还在」却跑的是旧进程</td><td style="text-align:left;">交接失败时旧进程刻意没退；或单例没重试导致接手没起来</td><td style="text-align:left;">§6、§9-2</td></tr><tr><td style="text-align:left;"><code>Failed to fetch</code> 但重启其实成了</td><td style="text-align:left;">chunked 截断报文</td><td style="text-align:left;">§6、§9-3</td></tr><tr><td style="text-align:left;"><code>&#39;C:\\Program&#39; 不是内部或外部命令</code></td><td style="text-align:left;">把 go 路径拼进 <code>cmd.exe /c</code></td><td style="text-align:left;">§7.2、§9-4</td></tr><tr><td style="text-align:left;">日志写「新二进制已就位」，exe 却没换</td><td style="text-align:left;"><code>ReplaceBinary</code> 同路径空操作</td><td style="text-align:left;">§6、§9-5</td></tr><tr><td style="text-align:left;">第二次不重建的重启报「文件被删了」</td><td style="text-align:left;"><code>os.Executable()</code> 仍指向 <code>next.exe</code></td><td style="text-align:left;">§9-6</td></tr><tr><td style="text-align:left;">「我明明改了，界面怎么没变」</td><td style="text-align:left;">漏了 embed 输入 / 忘了勾重建 / 只重编了 Go</td><td style="text-align:left;">§7.3、§2</td></tr><tr><td style="text-align:left;">「先重建」永远勾着</td><td style="text-align:left;">运行态文件被算成源码</td><td style="text-align:left;">§7.3、§9-8</td></tr><tr><td style="text-align:left;">重启后服务彻底没了，日志空白</td><td style="text-align:left;">detached 输出没落盘</td><td style="text-align:left;">§3、§9-9</td></tr><tr><td style="text-align:left;">重启成功两秒后又没了</td><td style="text-align:left;">共享控制台，关窗口把新服务带走</td><td style="text-align:left;">§3、§9-10</td></tr><tr><td style="text-align:left;">弹窗里出现字面量 <code>**加粗**</code></td><td style="text-align:left;">影响面写了 Markdown</td><td style="text-align:left;">§8.3、§9-11</td></tr><tr><td style="text-align:left;">按钮点了没反应</td><td style="text-align:left;">用了静态 <code>Modal.confirm</code> / <code>message</code>（拿不到 App 上下文）</td><td style="text-align:left;">§8.3</td></tr><tr><td style="text-align:left;">影响面里说明「会中断任务」，但任务还是被截断了</td><td style="text-align:left;">只在前端提示，服务端没设 409 门</td><td style="text-align:left;">§5.4-②</td></tr></tbody></table><hr><h2 id="_14-决策与备选" tabindex="-1"><a class="header-anchor" href="#_14-决策与备选"><span>14. 决策与备选</span></a></h2><table><thead><tr><th style="text-align:left;">决策</th><th style="text-align:left;">备选</th><th style="text-align:left;">为什么选这个</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>修订母本 §8/§15，做自重建</strong></td><td style="text-align:left;">继续「不做，手动 build」</td><td style="text-align:left;">当初的顾虑（失败无人看见）被 §2 三条硬约定解决；链路长的问题由自动勾重建 + 前端新鲜跳过 npm 解决。<strong>前提不满足时仍不做</strong></td></tr><tr><td style="text-align:left;">detached 接手进程</td><td style="text-align:left;">退出码 75 + <code>.new</code> 换身 + 启动器循环</td><td style="text-align:left;">启动器是最脆的一层（批处理解析 / 代码页 / 隐藏窗口 pause），不该再塞一个换身状态机；<code>.cmd</code> 一行不改</td></tr><tr><td style="text-align:left;">复用 <code>ui.json</code> 的 token</td><td style="text-align:left;">每次进程生成新 token</td><td style="text-align:left;">前端 token 没落盘，换了就 401，成功会被误报成失败</td></tr><tr><td style="text-align:left;">令牌从 0600 文件读，不进命令行</td><td style="text-align:left;">当 argv 传给子进程</td><td style="text-align:left;">命令行参数在任务管理器里看得见</td></tr><tr><td style="text-align:left;">单例互斥体带重试</td><td style="text-align:left;">拿不到就判「已有实例」</td><td style="text-align:left;">关监听在 <code>exit</code> 之前，锁晚几毫秒释放；误判会只开浏览器、服务却没起来</td></tr><tr><td style="text-align:left;"><code>boot_id</code> 作唯一判据</td><td style="text-align:left;">按「服务还在」/「请求成功」</td><td style="text-align:left;">交接失败时前者同样成立；后者在响应丢失时必然误报</td></tr><tr><td style="text-align:left;">传输层失败不算失败</td><td style="text-align:left;">任何异常都报失败</td><td style="text-align:left;">服务端先回 200 再退出，连接切断是预期形态</td></tr><tr><td style="text-align:left;">重建失败就地停</td><td style="text-align:left;">失败也重启 / 带旧二进制重启</td><td style="text-align:left;">后者会把「构建坏了」变成「服务没了」</td></tr><tr><td style="text-align:left;">备份类长任务在跑时 409 拒绝</td><td style="text-align:left;">只提示「会中断」</td><td style="text-align:left;">远端/数据库正在写，截断会留半状态</td></tr><tr><td style="text-align:left;">过期检测只有一份实现</td><td style="text-align:left;">重启一份、手工构建一份</td><td style="text-align:left;">两份会漂移成「重启说要重建、手工说不用」</td></tr><tr><td style="text-align:left;">自动勾「先重建」</td><td style="text-align:left;">默认勾 / 默认不勾</td><td style="text-align:left;">默认勾每次白等；默认不勾会用旧二进制起来</td></tr><tr><td style="text-align:left;">二次确认但<strong>不输 <code>yes</code></strong></td><td style="text-align:left;">沿用远端写操作的 <code>yes</code></td><td style="text-align:left;">重启是本机动作；多一次输入只会让人更少用它</td></tr><tr><td style="text-align:left;"><code>next.exe</code> + 旧进程退出后改名</td><td style="text-align:left;">直接 <code>build -o &lt;tool&gt;.exe</code></td><td style="text-align:left;">正在运行的 exe 被 Windows 锁着，覆盖只会拿到 sharing violation</td></tr><tr><td style="text-align:left;">非 Windows 明确报错</td><td style="text-align:left;">用 POSIX detach 假装能用</td><td style="text-align:left;">没验证过的「看起来能用」比明确失败更坏</td></tr><tr><td style="text-align:left;">全局顶部工具栏</td><td style="text-align:left;">某个页面的头部</td><td style="text-align:left;">对服务本身的动作，与当前页无关；不随页面卸载，轮询不中断</td></tr></tbody></table><hr><h2 id="_15-参考实现-只在核对细节时看" tabindex="-1"><a class="header-anchor" href="#_15-参考实现-只在核对细节时看"><span>15. 参考实现（只在核对细节时看）</span></a></h2><table><thead><tr><th style="text-align:left;">想确认</th><th style="text-align:left;">文件</th></tr></thead><tbody><tr><td style="text-align:left;">交接机制 / 重建 / 过期判定</td><td style="text-align:left;"><code>pass-up.ops/internal/restart/*.go</code></td></tr><tr><td style="text-align:left;">三个接口 / 六道门 / 确认令牌</td><td style="text-align:left;"><code>pass-up.ops/internal/ui/restart.go</code></td></tr><tr><td style="text-align:left;">接手子进程 / <code>__takeover</code></td><td style="text-align:left;"><code>pass-up.ops/restartchild.go</code>、<code>internal/ui/ui.go</code></td></tr><tr><td style="text-align:left;">前端判定 / 弹窗 / 工具栏</td><td style="text-align:left;"><code>pass-up.ops/web/src/features/system/</code>、<code>web/src/App.tsx</code></td></tr><tr><td style="text-align:left;">本仓实例文档（判据与验收）</td><td style="text-align:left;"><code>pass-up.ops/docs/ui.md</code> §11、<code>docs/one-click-launch.md</code> §4.2</td></tr><tr><td style="text-align:left;">另一份实现（<code>-allow-write=restart</code> 开关版）</td><td style="text-align:left;"><code>infra/wsl-manager/internal/restart/</code>、<code>internal/api/restart.go</code>、<code>docs/restart.md</code></td></tr><tr><td style="text-align:left;">被本文修订的母本</td><td style="text-align:left;"><code>cqlql-notes/docs/工程/桌面启动器与本地网页面板.md</code> §8 / §15</td></tr></tbody></table><blockquote><p>这些路径只作<strong>核对用</strong>。落地以本文 §3–§12 为准；参考实现里的项目名、端口、 exe 名、动词表一律不要照抄（换什么见 §11）。</p></blockquote><hr><h2 id="_16-待确认-已定稿" tabindex="-1"><a class="header-anchor" href="#_16-待确认-已定稿"><span>16. 待确认 / 已定稿</span></a></h2><table><thead><tr><th style="text-align:left;">优先级</th><th style="text-align:left;">事项</th><th style="text-align:left;">状态</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:left;">P1</td><td style="text-align:left;">给母本 §8 / §15 补一行「已修订，见本文」的指针</td><td style="text-align:left;">⚠️ 未做</td><td style="text-align:left;">两篇结论直接矛盾会误导 AI；<strong>建议补</strong>，但按笔记库约定不主动改既有文档</td></tr><tr><td style="text-align:left;">P1</td><td style="text-align:left;">新项目的「长任务判据」具体指哪些任务</td><td style="text-align:left;">待定</td><td style="text-align:left;">只把「会写外部状态」的任务算进去，纯查询类不必拦</td></tr><tr><td style="text-align:left;">P2</td><td style="text-align:left;">弹窗的视觉截图核对</td><td style="text-align:left;">⚠️ 本次只核对了产物类名与按钮启用态</td><td style="text-align:left;">新项目落地时补一次无头浏览器截图</td></tr><tr><td style="text-align:left;">P2</td><td style="text-align:left;"><code>ReplaceBinary</code> 失败后接手进程仍跑在 <code>next.exe</code> 上的处理</td><td style="text-align:left;">⚠️ 已知边界</td><td style="text-align:left;">日志已如实写明「这次重建没生效」；若下次带重建重启，<code>build -o next.exe</code> 会撞上正在运行的同名文件，需人工先把 <code>next.exe</code> 换到正式名</td></tr><tr><td style="text-align:left;">P2</td><td style="text-align:left;">是否需要 CLI 版「只重建不重启」</td><td style="text-align:left;">未做</td><td style="text-align:left;">低频，别给主路径加入口；真要加就复用同一份 <code>Rebuild</code></td></tr></tbody></table><h3 id="_16-1-已定稿、不再作为待确认项" tabindex="-1"><a class="header-anchor" href="#_16-1-已定稿、不再作为待确认项"><span>16.1 已定稿、不再作为待确认项</span></a></h3><ul><li>Windows 用 detached 接手进程，不用退出码 75 / 启动器循环。</li><li>非 Windows 明确报错，不做 POSIX 等价物。</li><li>界面重启不输 <code>yes</code>，但必须显式点击 + 二次确认 + 服务端确认令牌。</li><li>判据只有 <code>boot_id</code>；传输层失败不是失败。</li><li>启动器（<code>.cmd</code> / <code>.lnk</code>）不改动。</li></ul>`,119)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};